CustomField.formula:
IF(
    /* Check if the current month and year match the Time Entry Date */
    AND(
        MONTH(Time_Entry_Date__c) = MONTH(TODAY()), 
        YEAR(Time_Entry_Date__c) = YEAR(TODAY())
    ), 
    "This Month", /* If they match, display "This Month" */

    /* Check if the picklist month is the previous month and the year is the same */
    IF(
        AND(
            MONTH(Time_Entry_Date__c) = MONTH(TODAY()) - 1,
            YEAR(Time_Entry_Date__c)  = YEAR(TODAY())
        ), 
        "Last Month", /* If it matches, display "Last Month" */

        /* Check if the picklist month is the next month and the year is the same */
        IF(
            AND(
                MONTH(Time_Entry_Date__c) = MONTH(TODAY()) + 1,
                YEAR(Time_Entry_Date__c)  = YEAR(TODAY())
            ), 
            "Next Month", /* If it matches, display "Next Month" */

            "" /* If none of the above conditions are true, leave it blank */
        )
    )
)
